}> = ({ onFileSelect, onUrlSubmit, urlValue, onUrlChange, isFetchingUrl }) => {
    const [isDragging, setIsDragging] = useState(false);
    const inputRef = useRef<HTMLInputElement>(null);
    const { t } = useI18n();

    const handleFileChange = (files: FileList | null) => {
        if (files && files[0]) {
