const SupportChatPanel: React.FC = () => {
    const { t } = useI18n();
    const [history, setHistory] = useState<ChatMessage[]>([{
        id: 'init',
        sender: 'ai',
        text: t('support.assistant.initial' as TranslationKey),
    }]);
    const [input, setInput] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const chatSessionRef = useRef<Chat | null>(null);
    const chatEndRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        chatSessionRef.current = geminiService.startSupportChat();
    }, []);

    useEffect(() => {
        chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [history]);

    const handleSendMessage = async (e: React.FormEvent) => {
        e.preventDefault();
        const prompt = input.trim();
        if (!prompt || isLoading || !chatSessionRef.current) return;

        setInput('');
        setIsLoading(true);
        setHistory(prev => [...prev, { id: Date.now().toString(), sender: 'user', text: prompt }]);

        try {
            let response = await chatSessionRef.current.sendMessage({ message: prompt });

            if (response.functionCalls && response.functionCalls.length > 0) {
                 for (const fc of response.functionCalls) {
                    if (fc.name === 'checkApiStatus') {
                        const isOk = await geminiService.checkApiStatus();
                        const apiResult = isOk ? "La API funciona correctamente." : "Error: No se pudo conectar a la API.";

                        response = await chatSessionRef.current.sendMessage({
                            message: [{
                                functionResponse: {
                                    name: fc.name,
                                    response: { result: apiResult },
                                    id: fc.id
                                }
                            }]
                        });
                    }
                }
            }

            setHistory(prev => [...prev, { id: Date.now().toString() + 'ai', sender: 'ai', text: response.text }]);

        } catch (error) {
            const errorMessage = error instanceof Error ? error.message : "Error desconocido";
            setHistory(prev => [...prev, { id: Date.now().toString() + 'err', sender: 'ai', text: `Lo siento, ocurrió un error: ${errorMessage}` }]);
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="flex flex-col h-full">
            <div className="flex-grow p-4 overflow-y-auto space-y-4">
                {history.map((msg, i) => (
                    <div key={i} className={`flex items-start gap-3 ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
                        {msg.sender === 'ai' && <div className="w-8 h-8 rounded-full bg-primary flex-shrink-0 flex items-center justify-center font-bold text-white shadow-md">AI</div>}
                        <div className={`max-w-md px-4 py-2 rounded-2xl ${msg.sender === 'user' ? 'bg-primary/80 text-white' : 'bg-surface'}`}>
                            <article className="prose prose-invert prose-sm max-w-none"><ReactMarkdown remarkPlugins={[remarkGfm]}>{msg.text}</ReactMarkdown></article>
                        </div>
                    </div>
                ))}
                {isLoading && (
                     <div className="flex items-start gap-3 justify-start">
                        <div className="w-8 h-8 rounded-full bg-primary flex-shrink-0 flex items-center justify-center font-bold text-white shadow-md">AI</div>
                        <div className="px-4 py-3 rounded-2xl bg-surface">
                            <SpinnerIcon className="w-5 h-5 text-accent" />
                        </div>
                    </div>
                )}
                 <div ref={chatEndRef} />
            </div>
            <form onSubmit={handleSendMessage} className="p-2 border-t border-border">
                <div className="flex items-center gap-2 p-1.5 bg-background border-2 border-border rounded-xl focus-within:ring-2 focus-within:ring-primary">
                    <input value={input} onChange={e => setInput(e.target.value)} placeholder={t('support.assistant.placeholder' as TranslationKey)} className="w-full p-1 bg-transparent text-text-primary placeholder-text-tertiary outline-none" disabled={isLoading} />
                    <button type="submit" disabled={isLoading || !input.trim()} className="p-2 rounded-lg bg-primary text-white hover:bg-primary-focus disabled:bg-border"><SendIcon className="w-5 h-5" /></button>
                </div>
            </form>
        </div>
    );
};


export const SupportModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
}> = ({ isOpen, onClose }) => {
    const { t } = useI18n();
    const [activeTab, setActiveTab] = useState<Tab>('assistant');

    useEffect(() => {
        const handleEsc = (event: KeyboardEvent) => { if (event.key === 'Escape') onClose(); };
        if (isOpen) { window.addEventListener('keydown', handleEsc); }
        return () => window.removeEventListener('keydown', handleEsc);
    }, [isOpen, onClose]);

    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-50">
            <div className="fixed inset-0 bg-background/80 animate-fade-in z-40" onClick={onClose}/>
            <div className="flex items-center justify-center h-full">
                <div className="bg-surface border border-border rounded-lg shadow-xl w-full max-w-2xl h-[80vh] m-4 transform transition-all animate-slide-up flex flex-col relative z-50" onClick={(e) => e.stopPropagation()}>
                    <button
                        type="button"
                        onClick={onClose}
                        className="absolute top-3 right-3 p-1 rounded-full text-text-secondary hover:bg-border/50 text-2xl leading-none w-8 h-8 flex items-center justify-center z-10"
                        aria-label={t('common.close' as TranslationKey)}
                    >
                        &times;
                    </button>
                    <div className="p-4 border-b border-border">
                        <h2 className="text-xl font-bold text-text-primary flex items-center gap-2">
                            <HelpCircleIcon /> {t('support.title' as TranslationKey)}
                        </h2>
                    </div>
                    <div className="flex border-b border-border">
                        <button onClick={() => setActiveTab('assistant')} className={`flex-1 flex items-center justify-center gap-2 p-3 text-sm font-semibold border-b-2 transition-colors duration-200 ${activeTab === 'assistant' ? 'border-primary text-primary' : 'border-transparent text-text-secondary hover:text-white'}`}>
                            <BotIcon className="w-5 h-5"/> {t('support.tab.assistant' as TranslationKey)}
                        </button>
                        <button onClick={() => setActiveTab('faq')} className={`flex-1 flex items-center justify-center gap-2 p-3 text-sm font-semibold border-b-2 transition-colors duration-200 ${activeTab === 'faq' ? 'border-primary text-primary' : 'border-transparent text-text-secondary hover:text-white'}`}>
                            {t('support.tab.faq' as TranslationKey)}
                        </button>
                        <button onClick={() => setActiveTab('bug')} className={`flex-1 flex items-center justify-center gap-2 p-3 text-sm font-semibold border-b-2 transition-colors duration-200 ${activeTab === 'bug' ? 'border-primary text-primary' : 'border-transparent text-text-secondary hover:text-white'}`}>
                            <BugIcon className="w-5 h-5"/> {t('support.tab.bug' as TranslationKey)}
