                        <button onClick={() => setActiveTab('status')} className={`flex-1 flex items-center justify-center gap-2 p-3 text-sm font-semibold border-b-2 transition-colors duration-200 ${activeTab === 'status' ? 'border-primary text-primary' : 'border-transparent text-text-secondary hover:text-white'}`}>
                            <ActivityIcon className="w-5 h-5"/> {t('support.tab.status' as TranslationKey)}
                        </button>
                    </div>
                    <div className="flex-grow max-h-full overflow-y-auto min-h-0">
                        {activeTab === 'assistant' && <SupportChatPanel />}
                        {activeTab === 'faq' && <FAQPanel />}
                        {activeTab === 'bug' && <BugReportPanel />}
                        {activeTab === 'status' && <StatusPanel />}
                    </div>
                    <div className="p-4 bg-background/50 rounded-b-lg text-right border-t border-border">
                        <button onClick={onClose} className="px-6 py-2 bg-border text-white font-semibold rounded-lg hover:bg-border/70">{t('common.close' as TranslationKey)}</button>
                    </div>
                </div>
            </div>
        </div>
    );
};

