export const generateDependencyAnalysis = async (
    files: {path: string, content: string}[], 
    techStack: TechStack
): Promise<{
    dependencies: Omit<AnalysisIssue, 'category'>[];
    dependency_optimization: Omit<AnalysisIssue, 'category'>[];
}> => {
    const systemInstruction = dependencyAnalysisSystemInstruction;
    const techStackString = formatTechStack(techStack);

    // We send all files to allow cross-referencing imports with manifests
    const prompt = `Analiza el siguiente proyecto de software para detectar problemas relacionados con dependencias.

**Stack Tecnológico:**
${techStackString}

**Archivos del Proyecto (JSON):**
${JSON.stringify(files, null, 2)}

**Instrucciones:**
Realiza un análisis enfocado EXCLUSIVAMENTE en dependencias. Llena los siguientes campos en el JSON de salida y deja los demás vacíos:

1.  **dependencies:** Identifica dependencias con vulnerabilidades de seguridad conocidas (CVEs) o aquellas que estén severamente desactualizadas. Revisa los archivos de manifiesto (\`package.json\`, \`requirements.txt\`).
2.  **dependency_optimization:** Identifica dependencias NO UTILIZADAS. Cruza la lista de dependencias en los manifiestos con las importaciones (\`import\`, \`require\`) en los archivos de código fuente.
    *   Si una dependencia está listada en \`dependencies\` pero no se importa en ningún lugar, repórtala aquí.
    *   **IMPORTANTE:** Sé cauteloso con las \`devDependencies\` (ej. typescript, vite, eslint, @types/*). Estas herramientas de construcción y prueba a menudo no se importan en el código de la aplicación y NO deben marcarse como "no usadas" a menos que estés seguro de que son redundantes.

Responde únicamente con el objeto JSON que se adhiere al schema proporcionado.`;

    const response = await safeGenerateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
        config: {
            systemInstruction,
            responseMimeType: 'application/json',
            responseSchema: fullCodeAnalysisSchema, // Reuse the full schema but only populate specific fields
        }
    });

    try {
        let jsonStr = response.text.trim();
        if (jsonStr.startsWith('```json')) {
            jsonStr = jsonStr.substring(jsonStr.indexOf('\n') + 1, jsonStr.lastIndexOf('```'));
        }
        const jsonResponse = JSON.parse(jsonStr);
        // We only care about these two fields for this specific function
        return {
            dependencies: jsonResponse.dependencies || [],
            dependency_optimization: jsonResponse.dependency_optimization || []
        };
    } catch(e) {
        console.error("Failed to parse JSON response from AI:", response.text, e);
        throw new Error("La IA devolvió una respuesta JSON inválida.");
    }
};

    {uploadedFiles.length > 0 && (
        <div className="space-y-4">
            {stackWasAutoDetected && (
                <div className="flex items-center justify-center gap-2 text-sm text-accent animate-fade-in">
                    <LightbulbIcon className="w-4 h-4" />
                    <span>Stack tecnológico detectado o heredado. Puedes ajustarlo si es necesario.</span>
                </div>
            )}
            <div className="relative">
                {isDetectingStack && (
                    <div className="absolute inset-0 bg-surface/80 backdrop-blur-sm flex items-center justify-center z-10 rounded-lg">
                        <div className="flex items-center gap-2 text-accent">
                            <SpinnerIcon className="w-5 h-5" />
                            <span>Detectando stack tecnológico...</span>
                        </div>
                    </div>
                )}
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6 text-left">
                    <TechSelectionGroup category="frontend" title="Frontend" options={techOptions.frontend} selectedValue={techStack.frontend} onSelect={handleTechSelect} />
                    <TechSelectionGroup category="backend" title="Backend" options={techOptions.backend} selectedValue={techStack.backend} onSelect={handleTechSelect} />
                    <TechSelectionGroup category="database" title="Base de Datos" options={techOptions.database} selectedValue={techStack.database} onSelect={handleTechSelect} />
                </div>
            </div>
             <div className="pt-4">
                <ToggleSwitch
                    label="Iniciar análisis automáticamente al cargar"
                    checked={autoAnalyze}
                    onChange={setAutoAnalyze}
                />
            </div>
        </div>
    )}
    <div className="flex flex-col sm:flex-row items-center justify-center gap-4">
        <button
            type="submit" disabled={uploadedFiles.length === 0 || isLoading || isDetectingStack}
            className="w-full sm:w-auto px-8 py-3 bg-primary text-white font-bold text-lg rounded-lg hover:bg-primary-focus transition-transform transform hover:scale-105 duration-300 shadow-lg shadow-primary/20 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2">
            {isLoading ? <SpinnerIcon className="w-6 h-6" /> : <StethoscopeIcon className="w-6 h-6" />}
            {isLoading ? 'Analizando...' : 'Análisis Completo'}
        </button>
         <button
            type="button" onClick={onStartDependencyAnalysis} disabled={uploadedFiles.length === 0 || isLoading || isDetectingStack}
            className="w-full sm:w-auto px-6 py-2 bg-orange-500/20 text-orange-400 font-semibold rounded-lg hover:bg-orange-500/30 transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2">
            {isLoading ? <SpinnerIcon className="w-5 h-5" /> : <BugIcon className="w-5 h-5" />}
            {isLoading ? 'Analizando...' : 'Dependencias y Uso'}
        </button>
         <button
            type="button" onClick={onStartBestPracticesAnalysis} disabled={uploadedFiles.length === 0 || isLoading || isDetectingStack}
            className="w-full sm:w-auto px-6 py-2 bg-info/20 text-info font-semibold rounded-lg hover:bg-info/30 transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2">
            {isLoading ? <SpinnerIcon className="w-5 h-5" /> : <LightbulbIcon className="w-5 h-5" />}
            {isLoading ? 'Analizando...' : 'Solo Mejores Prácticas'}
        </button>
    </div>
</form>

