const ArchitectFlow: React.FC<{onSendToDoctor: () => void; onSendToDeployer: () => void;}> = React.memo(({ onSendToDoctor, onSendToDeployer }) => {
    const { 
        architectStep, 
        isLoading, 
        loadingText, 
        error, 
        submitBlueprint, 
        generateArchitecture, 
        fileStructure,
        requestModification,
        setStep,
        clarificationHistory,
        projectDescription,
        techStack,
        resetArchitect
     } = useArchitectContext();

     const handleStartNew = () => {
        resetArchitect();
     }

    const steps = ['Prototipo', 'Aclaración', 'Vista Previa', 'Entrega'];
    const stepMap: Record<typeof architectStep, number> = {
        'blueprint': 0,
        'clarification': 1,
        'preview': 2,
        'delivery': 3,
    };
    const currentStepIndex = stepMap[architectStep];

    let stepComponent;
    switch (architectStep) {
        case 'blueprint':
            stepComponent = <Step1Blueprint onSubmit={submitBlueprint} />;
            break;
        case 'clarification':
            stepComponent = <Step2Clarification onSubmit={generateArchitecture} initialHistory={clarificationHistory} />;
            break;
        case 'preview':
            stepComponent = fileStructure && <Step3Preview fileStructure={fileStructure} onModificationRequest={requestModification} onApproval={() => setStep('delivery')} />;
            break;
        case 'delivery':
            stepComponent = fileStructure && projectDescription && techStack && <Step4Delivery fileStructure={fileStructure} projectDescription={projectDescription} techStack={techStack} onStartNew={handleStartNew} onSendToDoctor={onSendToDoctor} onSendToDeployer={onSendToDeployer} />;
            break;
        default:
            stepComponent = <div>Error: unknown step.</div>;
    }

    return (
         <div className="flex flex-col h-full w-full items-center pt-8">
            {isLoading && <Loader text={loadingText} />}
            <main className="w-full max-w-7xl flex-grow flex flex-col items-center mt-8 px-4">
                 <div className="w-full max-w-xl mb-16">
                     <Stepper currentStep={currentStepIndex} steps={steps} />
                 </div>
                {error && <div className="bg-error/10 border border-error/30 text-red-300 px-4 py-3 rounded-lg relative my-4 w-full" role="alert">{error}</div>}
                {stepComponent}
            </main>
         </div>
    );
});

