                            return <ArchitectFlow onSendToDoctor={handleSendToDoctor} onSendToDeployer={handleSendToDeployer} />;
                        case 'doctor':
                            return <CodeDoctorFlow />;
                        case 'tutor':
                            return <TestTutorFlow />;
                        case 'magician':
                            return <UIMagicianFlow onSendToDoctor={handleSendToDoctorFromMagician} />;
                        case 'deployer':
                            return <DeployerFlow />;
                        case 'community':
                            return <CommunityHubFlow />;
                        case 'wireframe':
                            return <WireframeFlow onSendToDoctor={handleSendToDoctorFromWireframe} />;
                        case 'translator':
                            return <CodeTranslatorFlow />;
                        case 'donation':
                             return <DonationFlow />;
                        case 'videoAnalyst':
                            return <VideoAnalystFlow />;
                        case 'codeCopilot':
                            return <CodeCopilotFlow />;
                        case 'navigator':
                            return <WebNavigatorFlow onSendToDoctor={handleSendToDoctorFromNavigator} onAnalyzeFilesInDoctor={handleAnalyzeFilesInDoctor}/>;
                        case 'liveChat': // New Live Chat Mode
                            return <LiveChatFlow />;
                        default:
                            return <div>Módulo no encontrado.</div>;
                    }
                })()}
            </Suspense>
        );
    };

    return (
        <div className="flex h-screen bg-background relative">
            {activeMode && (
                <SidebarNav 
                    activeMode={activeMode} 
                    isSidebarVisible={isSidebarVisible}
                    onSelectMode={handleSelectMode} 
                    onReset={handleReset}
                    onOpenSettings={() => openModal('settings', { speechHook })}
                    onOpenSupport={() => openModal('support', {})}
                    currentUser={currentUser}
                    onOpenAuth={() => openModal('auth', {})}
                    onLogout={onLogout}
                    onToggleSidebar={() => setIsSidebarVisible(!isSidebarVisible)}
                />
            )}
            <div className={`flex-grow h-screen overflow-y-auto transition-all duration-300 ${!activeMode ? 'w-full' : ''}`}>
                {renderContent()}
            </div>
        </div>
    );
};


