import { useState, useEffect, useCallback } from 'react';
import { ChatMessage, CodeDiagnostic, Conversation } from '../types';
import * as geminiService from '../services/geminiService';
import { Chat, Part } from '@google/genai';
import { useToastContext } from '../contexts/ToastContext';
import { useProjectContext } from '../contexts/ProjectContext';
import { useI18n } from '../contexts/I18nContext';
import { SendIcon, CopyIcon, MicrophoneIcon, PlayCircleIcon, PauseCircleIcon, PaperclipIcon, FileIcon, ImageIcon, RefreshIcon, SettingsIcon, SpeakerOnIcon, SpeakerOffIcon, HistoryIcon, StethoscopeIcon, ThumbsUpIcon, ThumbsDownIcon, CodeIcon, SpinnerIcon } from '../components/ui/icons';
import { CodeBlock } from '../components/ui/CodeBlock';

type AttachedFile = {
    name: string;
    mimeType: string;
    content: string; // Text content or base64 string
    isImage: boolean;
    isVideo: boolean;
    previewUrl?: string; // Data URL for image/video preview
    contentSnippet?: string; // for text files
    isLoading: boolean;
};


const generateId = () => Date.now().toString(36) + Math.random().toString(36).substring(2);
const ACTIVE_CHAT_STORAGE_KEY = 'alphapp-ai-chat-history';
const CHAT_LOG_STORAGE_KEY = 'alphapp-ai-chat-log';

export const useChat = () => {
    const { t } = useI18n();
    const { addToast } = useToastContext();
    const { projectFiles, isProjectLoaded } = useProjectContext();
    const [isProjectContextEnabled, setIsProjectContextEnabled] = useState(false);

    const [chatSession, setChatSession] = useState<Chat | null>(null);

    const [conversationLog, setConversationLog] = useState<Conversation[]>(() => {
        try {
            const savedLog = window.localStorage.getItem(CHAT_LOG_STORAGE_KEY);
            return savedLog ? JSON.parse(savedLog) : [];
        } catch (error) {
            console.error("Could not load chat log from localStorage", error);
            return [];
        }
    });

    const [currentConversationId, setCurrentConversationId] = useState<string | null>(null);

    const [chatHistory, setChatHistory] = useState<ChatMessage[]>(() => {
        try {
            const savedHistory = window.localStorage.getItem(ACTIVE_CHAT_STORAGE_KEY);
            if (savedHistory) {
                const parsedHistory = JSON.parse(savedHistory);
                if (Array.isArray(parsedHistory) && parsedHistory.length > 0) {
                    return parsedHistory;
                }
            }
        } catch (error) {
            console.error("Could not load chat history from localStorage", error);
        }
        return [
            { 
                id: generateId(),
                sender: 'ai', 
                text: t('chat.initialMessage'),
                timestamp: Date.now()
            }
        ];
    });

    const [inputText, setInputText] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [attachedFiles, setAttachedFiles] = useState<AttachedFile[]>([]);
    const [followUpSuggestions, setFollowUpSuggestions] = useState<string[]>([]);

    const saveCurrentConversation = useCallback(async () => {
        // Only save if there's more than the initial AI message
        if (chatHistory.length <= 1 && attachedFiles.length === 0) return;

        let title = "Nueva Conversación";
        let updatedLog = [...conversationLog];

        if (currentConversationId) {
            // Update existing conversation
            const index = updatedLog.findIndex(c => c.id === currentConversationId);
            const conversationToUpdate = updatedLog[index];
            if (index !== -1) {
                // FIX: Added timestamp to conversation update
                title = conversationToUpdate.title;
                updatedLog[index] = { ...conversationToUpdate, messages: chatHistory, timestamp: Date.now() };
            } else {
                // This case should ideally not happen, but as a fallback, create a new one
                // FIX: Added timestamp to new conversation
                const newConversation: Conversation = { id: currentConversationId, title, timestamp: Date.now(), messages: chatHistory };
                updatedLog.unshift(newConversation);
            }
        } else {
            // Create new conversation
            const firstUserMessage = chatHistory.find(m => m.sender === 'user')?.text;
            if (firstUserMessage) {
                try {
                    // Generate a concise title from the first message
                    title = await geminiService.getQuickAnswer(`Genera un título muy corto (máximo 5 palabras) para una conversación que empieza con: "${firstUserMessage}"`);
                } catch (e) {
                    console.error("Failed to generate title:", e);
                    title = firstUserMessage.substring(0, 30) + '...';
                }
            }

            const newId = generateId();
            // FIX: Added timestamp to new conversation
            const newConversation: Conversation = { id: newId, title, timestamp: Date.now(), messages: chatHistory };
            updatedLog.unshift(newConversation);
            setCurrentConversationId(newId);
        }
        setConversationLog(updatedLog);

        try {
            window.localStorage.setItem(CHAT_LOG_STORAGE_KEY, JSON.stringify(updatedLog));
        } catch (error) {
            console.error("Could not save chat log to localStorage", error);
        }
    }, [chatHistory, conversationLog, currentConversationId, attachedFiles.length]);

    useEffect(() => {
        try {
            window.localStorage.setItem(ACTIVE_CHAT_STORAGE_KEY, JSON.stringify(chatHistory));
        } catch (error) {
            console.error("Could not save chat history to localStorage", error);
        }
    }, [chatHistory]);

    useEffect(() => {
        setChatSession(geminiService.startChat(chatHistory));
        // We only want this to run once on initial load.
        // Re-initialization is handled by loadConversation and resetChat
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    const addFiles = useCallback((files: FileList) => {
        if (!files) return;

        for (const file of Array.from(files)) {
            const reader = new FileReader();
            const isImage = file.type.startsWith('image/');
            const isVideo = file.type.startsWith('video/');

            setAttachedFiles(prev => [...prev, {
                name: file.name,
                mimeType: file.type,
                content: '',
                isImage,
                isVideo,
                isLoading: true
            }]);

            reader.onload = (e) => {
                const result = e.target?.result as string;

                setAttachedFiles(prev => prev.map(f => f.name === file.name ? {
                    ...f,
                    content: result.includes(',') ? result.split(',')[1] : result,
                    previewUrl: (isImage || isVideo) ? result : undefined,
                    contentSnippet: (!isImage && !isVideo) ? result.substring(0, 100) : undefined,
                    isLoading: false
                } : f));
            };

            reader.onerror = () => {
                 addToast({ type: 'error', title: 'Error de Archivo', message: `No se pudo leer el archivo ${file.name}` });
                 setAttachedFiles(prev => prev.filter(f => f.name !== file.name));
            };

            if (isImage || isVideo) {
                reader.readAsDataURL(file);
            } else {
                reader.readAsText(file);
            }
        }
    }, [addToast]);

    const removeFile = useCallback((name: string) => {
        setAttachedFiles(prev => prev.filter(f => f.name !== name));
    }, []);

    const sendMessage = useCallback(async (message: string) => {
        if (isLoading || !chatSession) return;

        setIsLoading(true);
        setError(null);
        setFollowUpSuggestions([]);

        const userMessage: ChatMessage = {
            id: generateId(),
            sender: 'user',
            text: message,
            timestamp: Date.now(),
            files: attachedFiles.map(f => ({ name: f.name, isImage: f.isImage, isVideo: f.isVideo })),
        };
        const currentHistoryWithUserMessage = [...chatHistory, userMessage];
        setChatHistory(currentHistoryWithUserMessage);

        const parts: (string | Part)[] = [{ text: message }];
        attachedFiles.forEach(file => {
            parts.push({
                inlineData: { mimeType: file.mimeType, data: file.content },
            });
        });

        if (isProjectContextEnabled && projectFiles && projectFiles.length > 0) {
            const projectContext = projectFiles.map(f => `--- ${f.path} ---\n${f.content}`).join('\n\n');
            parts.unshift({ text: `Contexto del proyecto:\n\`\`\`\n${projectContext}\n\`\`\`\n\nPregunta del usuario:` });
            addToast({ type: 'info', title: 'Contexto Enviado', message: 'Se ha enviado el contexto del proyecto junto con tu mensaje.' });
        }

        setAttachedFiles([]);

        const aiMessageId = generateId();
        setChatHistory(prev => [...prev, { id: aiMessageId, sender: 'ai', text: '', sources: [], timestamp: Date.now() }]);

        try {
            const stream = await geminiService.sendMessageToAI(chatSession, parts);
            let fullResponse = '';
            for await (const chunk of stream) {
                const groundingMetadata = chunk.candidates?.[0]?.groundingMetadata;
                if (groundingMetadata?.groundingChunks) {
                    const sources = groundingMetadata.groundingChunks.map(c => c.web).filter(web => web?.uri) as { uri: string; title: string }[];
                    if (sources.length > 0) {
                        setChatHistory(prev => {
                            const newHistory = [...prev];
                            const lastMessage = newHistory[newHistory.length - 1];
                            if (lastMessage?.sender === 'ai') {
                                const existingUris = new Set((lastMessage.sources || []).map(s => s.uri));
                                const newSources = sources.filter(s => !existingUris.has(s.uri));
                                if (newSources.length > 0) {
                                    lastMessage.sources = [...(lastMessage.sources || []), ...newSources];
                                }
                            }
                            return newHistory;
                        });
                    }
                }

                if (chunk.text) {
                    fullResponse += chunk.text;
                    setChatHistory(prev => {
                        const newHistory = [...prev];
                        newHistory[newHistory.length - 1] = { ...newHistory[newHistory.length - 1], text: fullResponse };
                        return newHistory;
                    });
                }
            }

            // FIX: Explicitly type the AI message object to ensure it matches the ChatMessage type.
            const aiResponseMessage: ChatMessage = { id: aiMessageId, sender: 'ai', text: fullResponse, timestamp: Date.now() };
            const finalHistory = [...currentHistoryWithUserMessage, aiResponseMessage];
            const suggestions = await geminiService.generateFollowUpSuggestions(finalHistory);
            setFollowUpSuggestions(suggestions);

        } catch (e) {
            const errorMessage = e instanceof Error ? e.message : 'Ocurrió un error desconocido.';
            setError(errorMessage);
            setChatHistory(prev => {
                const newHistory = [...prev];
                newHistory[newHistory.length - 1] = { ...newHistory[newHistory.length - 1], text: `Error: ${errorMessage}` };
                return newHistory;
            });
        } finally {
            setIsLoading(false);
            saveCurrentConversation();
        }
    }, [isLoading, chatSession, attachedFiles, isProjectContextEnabled, projectFiles, addToast, chatHistory, saveCurrentConversation]);

    const resetChat = useCallback(async () => {
        await saveCurrentConversation();

        setCurrentConversationId(null);
        const initialMessage: ChatMessage = { id: generateId(), sender: 'ai', text: t('chat.initialMessage'), timestamp: Date.now() };
        setChatHistory([initialMessage]);
        setInputText('');
        setAttachedFiles([]);
        setFollowUpSuggestions([]);
        setError(null);

        setChatSession(geminiService.startChat());
    }, [saveCurrentConversation, t]);

    const loadConversation = useCallback((id: string) => {
        saveCurrentConversation();

        const conversationToLoad = conversationLog.find(c => c.id === id);
        if (conversationToLoad) {
            setChatHistory(conversationToLoad.messages);
            setCurrentConversationId(id);
            setAttachedFiles([]);
            setFollowUpSuggestions([]);
            setError(null);

            setChatSession(geminiService.startChat(conversationToLoad.messages));

            addToast({ type: 'info', title: 'Conversación Cargada', message: `Se ha cargado "${conversationToLoad.title}".` });
        } else {
            addToast({ type: 'error', title: 'Error', message: 'No se pudo encontrar la conversación.' });
        }
    }, [conversationLog, saveCurrentConversation, addToast]);

    const deleteConversation = useCallback((id: string) => {
        const updatedLog = conversationLog.filter(c => c.id !== id);
        setConversationLog(updatedLog);

        try {
            window.localStorage.setItem(CHAT_LOG_STORAGE_KEY, JSON.stringify(updatedLog));
            addToast({ type: 'success', title: 'Conversación Eliminada', message: 'La conversación ha sido eliminada.' });
        } catch (error) {
            console.error("Could not save chat log to localStorage", error);
        }

        if (currentConversationId === id) {
            resetChat();
        }
    }, [conversationLog, currentConversationId, resetChat, addToast]);

    const setMessageFeedback = useCallback((messageId: string, feedback: 'good' | 'bad') => {
        setChatHistory(prev =>
            prev.map(msg =>
                msg.id === messageId
                    ? { ...msg, feedback: msg.feedback === feedback ? undefined : feedback }
                    : msg
            )
        );
    }, []);

    const toggleProjectContext = useCallback(() => {
        if (isProjectLoaded) {
            setIsProjectContextEnabled(prev => !prev);
        } else {
            addToast({ type: 'warning', title: 'Sin Proyecto', message: 'Carga un proyecto en el Arquitecto o Doctor para usar esta función.' });
        }
    }, [isProjectLoaded, addToast]);

    return {
        chatHistory,
        sendMessage,
        isLoading,
        error,
        inputText,
        setInputText,
        attachedFiles,
        addFiles,
        removeFile,
        resetChat,
        conversationLog,
        loadConversation,
        deleteConversation,
        followUpSuggestions,
        setMessageFeedback,
        isProjectLoaded,
        isProjectContextEnabled,
        toggleProjectContext
    };
};

