export const editImage = async (image: string, mimeType: string, instruction: string): Promise<ImageEditResult> => {
    // Using image editing model
    const prompt = instruction;
    const response = await safeGenerateContent({
        model: 'gemini-2.5-flash-image',
        contents: {
            parts: [
                { inlineData: { mimeType, data: image } },
                { text: prompt }
            ]
        }
    });

    // Parse response for image
    let editedImage = null;
    let text = null;

    if (response.candidates && response.candidates[0].content.parts) {
        for (const part of response.candidates[0].content.parts) {
            if (part.inlineData) {
                editedImage = { base64: part.inlineData.data, mimeType: part.inlineData.mimeType };
            } else if (part.text) {
                text = part.text;
            }
        }
    }

    return { editedImage, text };
};

