}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [currentUser, setCurrentUser] = useState<User | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const { addToast } = useToastContext();

    useEffect(() => {
        if (!auth) {
            console.warn("Firebase Auth not initialized.");
            setIsLoading(false);
            return;
        }

        const unsubscribe = onAuthStateChanged(auth, async (firebaseUser: FirebaseUser | null) => {
            if (firebaseUser) {
                // Fetch extended user profile from Firestore
                const userProfile = await getUserProfile(firebaseUser.uid);
                if (userProfile) {
                    setCurrentUser(userProfile);
                } else {
                    // Fallback if profile missing (shouldn't happen on new register)
                    setCurrentUser({
                        uid: firebaseUser.uid,
                        email: firebaseUser.email || '',
                        username: firebaseUser.displayName || 'User',
                        lang: 'es',
                        persona: 'Desarrollador'
                    });
                }
            } else {
                setCurrentUser(null);
            }
            setIsLoading(false);
        });

        return () => unsubscribe();
    }, []);

    const login = async (email: string, password: string): Promise<boolean> => {
        if (!auth) {
            addToast({ type: 'error', title: 'Error de Configuración', message: 'Firebase no está configurado.' });
            return false;
        }
        try {
            await signInWithEmailAndPassword(auth, email, password);
            addToast({ type: 'success', title: '¡Bienvenido!', message: 'Has iniciado sesión exitosamente.' });
            return true;
        } catch (error: any) {
            console.error("Login failed:", error);
            let message = 'Error de inicio de sesión.';
            if (error.code === 'auth/user-not-found' || error.code === 'auth/wrong-password' || error.code === 'auth/invalid-credential') {
                message = 'Email o contraseña incorrectos.';
            } else if (error.code === 'auth/invalid-email') {
                message = 'El formato del email no es válido.';
            }
            addToast({ type: 'error', title: 'Error', message });
            return false;
        }
    };

    const register = async (email: string, password: string, lang: 'es' | 'en', persona: 'Desarrollador' | 'QA' | 'DevOps'): Promise<boolean> => {
        if (!auth) {
            addToast({ type: 'error', title: 'Error de Configuración', message: 'Firebase no está configurado.' });
            return false;
        }
        try {
            const userCredential = await createUserWithEmailAndPassword(auth, email, password);
            const user = userCredential.user;

            const newUser: User = {
                uid: user.uid,
                email: user.email || email,
                username: email.split('@')[0], // Default username from email
                lang,
                persona
            };

            await saveUserProfile(newUser);
            setCurrentUser(newUser);

            addToast({ type: 'success', title: '¡Registro exitoso!', message: 'Tu cuenta ha sido creada.' });
            return true;
        } catch (error: any) {
            console.error("Registration failed:", error);
            let message = 'Ocurrió un error al registrarse.';
            if (error.code === 'auth/email-already-in-use') {
                message = 'El correo electrónico ya está en uso.';
            } else if (error.code === 'auth/weak-password') {
                message = 'La contraseña es muy débil (mínimo 6 caracteres).';
            }
            addToast({ type: 'error', title: 'Error', message });
            return false;
        }
    };

    const logout = async () => {
        if (!auth) return;
        try {
            await signOut(auth);
            setCurrentUser(null);
            addToast({ type: 'info', title: 'Sesión cerrada', message: 'Has cerrado sesión exitosamente.' });
        } catch (error) {
            console.error("Logout failed", error);
        }
    };

    const value = {
        currentUser,
        isAuthenticated: !!currentUser,
        login,
        register,
        logout,
        isLoading
    };

    return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

export const useAuthContext = () => {
    const context = useContext(AuthContext);
    if (context === undefined) {
        throw new Error('useAuthContext must be used within an AuthProvider');
    }
    return context;
};

import { doc, setDoc, getDoc, updateDoc } from 'firebase/firestore';
import { db } from './firebase';
import { User } from '../types';

export const saveUserProfile = async (user: User) => {
    if (!user.uid) return;
    if (!db) {
        console.warn("Firestore not initialized. Cannot save profile.");
        return;
    }
    try {
        const userRef = doc(db, 'users', user.uid);
        await setDoc(userRef, {
            uid: user.uid,
            username: user.username,
            email: user.email,
            lang: user.lang,
            persona: user.persona,
            lastLogin: new Date().toISOString()
        }, { merge: true });
    } catch (error) {
        console.error("Error saving user profile:", error);
        throw error;
    }
};

export const getUserProfile = async (uid: string): Promise<User | null> => {
    if (!db) {
        console.warn("Firestore not initialized. Cannot get profile.");
        return null;
    }
    try {
        const userRef = doc(db, 'users', uid);
        const docSnap = await getDoc(userRef);

        if (docSnap.exists()) {
            return docSnap.data() as User;
        } else {
            return null;
        }
    } catch (error) {
        console.error("Error getting user profile:", error);
        return null;
    }
};

import React, { Component, ErrorInfo, ReactNode } from 'react';
import { AlertTriangleIcon } from './ui/icons';
import { I18nContext } from '../contexts/I18nContext';

interface ErrorBoundaryProps {
  children?: ReactNode; // Made optional to be safe, though usually required
}

interface ErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
}

export class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  public state: ErrorBoundaryState = { hasError: false, error: null };

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Uncaught error:", error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <I18nContext.Consumer>
          {(i18n) => {
            const t = i18n?.t || ((key: string) => key);
            return (
              <div className="flex flex-col items-center justify-center h-screen bg-background text-text-primary p-8">
                <AlertTriangleIcon className="w-24 h-24 text-error mb-6" />
                <h1 className="text-4xl font-bold text-error mb-4">{t('errorBoundary.title')}</h1>
                <p className="text-lg text-text-secondary max-w-2xl text-center mb-8">
                  {t('errorBoundary.description')}
                </p>

                <div className="bg-surface p-4 rounded-lg w-full max-w-2xl font-mono text-sm text-error/80 mb-8">
                  <p className="font-bold">{t('errorBoundary.details')}</p>
                  <pre className="whitespace-pre-wrap mt-2">{this.state.error?.message || t('errorBoundary.unknown')}</pre>
                </div>

                <div className="flex gap-4">
                  <button
                    onClick={() => window.location.reload()}
                    className="px-6 py-3 bg-primary text-white font-semibold rounded-lg hover:bg-primary-focus transition-colors text-lg"
                  >
                    {t('errorBoundary.reload')}
                  </button>
                </div>
              </div>
            );
          }}
        </I18nContext.Consumer>
      );
    }

    return this.props.children;
  }
}

