export const generateVideoFromImageAndPrompt = async (imageBytes: string, mimeType: string, prompt: string, aspectRatio: string, onProgress: (p: number, m: string) => void): Promise<string> => {
    onProgress(10, 'Iniciando generación...');

    try {
        onProgress(30, 'Procesando solicitud...');
        const operation = await ai.models.generateVideos({
            model: 'veo-3.1-fast-generate-preview',
            prompt: prompt,
            image: { imageBytes, mimeType },
            config: {
                numberOfVideos: 1,
                aspectRatio: aspectRatio as any 
            }
        });

        let op = operation;
        while (!op.done) {
            await new Promise(resolve => setTimeout(resolve, 5000));
            onProgress(50, 'Generando frames...');
            op = await ai.operations.getVideosOperation({operation: op});
        }

        onProgress(90, 'Finalizando...');
        const videoUri = op.response?.generatedVideos?.[0]?.video?.uri;
        if (!videoUri) throw new Error("No video URI returned");

        const res = await fetch(`${videoUri}&key=${process.env.API_KEY}`);
        const blob = await res.blob();
        return URL.createObjectURL(blob);
    } catch (e) {
        console.error(e);
        throw e;
    }
};

