export const createBlob = (data: Float32Array): any => {
    const l = data.length;
    const int16 = new Int16Array(l);
    for (let i = 0; i < l; i++) {
        int16[i] = data[i] * 32768;
    }
    return {
        data: encode(new Uint8Array(int16.buffer)),
        mimeType: 'audio/pcm;rate=16000',
    };
};

export function decode(base64: string) {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
}

export function encode(bytes: Uint8Array) {
    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
        binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
}

export async function decodeAudioData(
    data: Uint8Array,
    ctx: AudioContext,
    sampleRate: number,
    numChannels: number,
): Promise<AudioBuffer> {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

    for (let channel = 0; channel < numChannels; channel++) {
        const channelData = buffer.getChannelData(channel);
        for (let i = 0; i < frameCount; i++) {
            channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
        }
    }
    return buffer;
}

import React, { Component, ErrorInfo, ReactNode } from 'react';
import { AlertTriangleIcon } from './ui/icons';
import { I18nContext } from '../contexts/I18nContext';

interface ErrorBoundaryProps {
  children?: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
}

export class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  public state: ErrorBoundaryState = { hasError: false, error: null };

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Uncaught error:", error, errorInfo);
  }

  render(): ReactNode {
    if (this.state.hasError) {
      return (
        <I18nContext.Consumer>
          {(i18n) => {
            const t = i18n?.t || ((key: string) => key);
            return (
              <div className="flex flex-col items-center justify-center h-screen bg-background text-text-primary p-8">
                <AlertTriangleIcon className="w-24 h-24 text-error mb-6" />
                <h1 className="text-4xl font-bold text-error mb-4">{t('errorBoundary.title' as any)}</h1>
                <p className="text-lg text-text-secondary max-w-2xl text-center mb-8">
                  {t('errorBoundary.description' as any)}
                </p>

                <div className="bg-surface p-4 rounded-lg w-full max-w-2xl font-mono text-sm text-error/80 mb-8">
                  <p className="font-bold">{t('errorBoundary.details' as any)}</p>
                  <pre className="whitespace-pre-wrap mt-2">{this.state.error?.message || t('errorBoundary.unknown' as any)}</pre>
                </div>

                <div className="flex gap-4">
                  <button
                    onClick={() => window.location.reload()}
                    className="px-6 py-3 bg-primary text-white font-semibold rounded-lg hover:bg-primary-focus transition-colors text-lg"
                  >
                    {t('errorBoundary.reload' as any)}
                  </button>
                </div>
              </div>
            );
          }}
        </I18nContext.Consumer>
      );
    }

    return this.props.children;
  }
}

