// --- Video Analyst ---

export const generateVideoFromImageAndPrompt = async (imageBytes: string, mimeType: string, prompt: string, aspectRatio: AspectRatio, onProgress: (p: number, m: string) => void): Promise<string> => {
    const ai = getAI();
    onProgress(10, 'Iniciando generación de video...');

    try {
        const operation = await ai.models.generateVideos({
            model: 'veo-3.1-fast-generate-preview',
            prompt: prompt,
            image: { imageBytes, mimeType },
            config: {
                numberOfVideos: 1,
                aspectRatio: aspectRatio as any,
                resolution: '720p' // Mandatory parameter
            }
        });

        let op = operation;
        while (!op.done) {
            await new Promise(resolve => setTimeout(resolve, 10000));
            onProgress(50, 'Generando frames de alta calidad...');
            op = await ai.operations.getVideosOperation({operation: op});
        }

        onProgress(90, 'Finalizando archivo MP4...');
        const videoUri = op.response?.generatedVideos?.[0]?.video?.uri;
        if (!videoUri) throw new Error("No se pudo obtener el URI del video.");

        const res = await fetch(`${videoUri}&key=${process.env.API_KEY}`);
        const blob = await res.blob();
        return URL.createObjectURL(blob);
    } catch (e) {
        console.error(e);
        throw e;
    }
};

