export const ChatInterface: React.FC<ChatInterfaceProps> = ({
    chatHistory, onSendMessage, isLoading, inputValue, onInputChange, isListening,
    startListening, stopListening, onSpeak, cancelSpeaking, speakingText,
    attachedFiles, onAddFiles, onRemoveFile, onResetChat, isTtsEnabled, onToggleTts,
    onOpenVoiceModal, onOpenHistory, context = 'chat', followUpSuggestions = [],
    setMessageFeedback, isProjectLoaded = false, isProjectContextEnabled = false, onToggleProjectContext = () => {},
}) => {
    const messagesEndRef = useRef<HTMLDivElement>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);
    const [isDragging, setIsDragging] = useState(false);
    const dragCounter = useRef(0);

    useEffect(() => { messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [chatHistory]);

    const handleFormSubmit = (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        if (isLoading || (!inputValue.trim() && attachedFiles.length === 0)) return;
        onSendMessage(inputValue);
        onInputChange('');
    };

    const handleDragEnter = (e: React.DragEvent) => { e.preventDefault(); dragCounter.current++; if (e.dataTransfer.items.length > 0) setIsDragging(true); };
    const handleDragLeave = (e: React.DragEvent) => { e.preventDefault(); dragCounter.current--; if (dragCounter.current === 0) setIsDragging(false); };
    const handleDrop = (e: React.DragEvent) => { e.preventDefault(); setIsDragging(false); dragCounter.current = 0; if (e.dataTransfer.files.length > 0) onAddFiles(e.dataTransfer.files); };
    const handlePaste = (e: React.ClipboardEvent) => { if (e.clipboardData.files.length > 0) { e.preventDefault(); onAddFiles(e.clipboardData.files); } };

    return (
        <div className="flex flex-col h-full relative" onDragEnter={handleDragEnter} onDragLeave={handleDragLeave} onDragOver={e => e.preventDefault()} onDrop={handleDrop} onPaste={handlePaste}>
            {isDragging && (
                <div className="absolute inset-0 bg-primary/20 border-4 border-dashed border-primary rounded-3xl z-30 flex flex-col items-center justify-center pointer-events-none backdrop-blur-md animate-pulse">
                    <div className="w-32 h-32 rounded-full bg-primary/20 flex items-center justify-center mb-6"><FileIcon className="w-16 h-16 text-primary" /></div>
                    <p className="text-3xl font-black text-white drop-shadow-lg">Suelta para Importar</p>
                </div>
            )}

            <div className="flex-shrink-0 flex items-center justify-between p-4 border-b border-border/30 bg-background/50 backdrop-blur-xl">
                <h2 className="text-xl font-black text-text-primary tracking-tight">AI Workspace</h2>
                <div className="flex items-center gap-1.5">
                    <button onClick={onOpenHistory} className="p-2.5 rounded-xl text-text-secondary hover:bg-surface hover:text-white transition-all shadow-sm"><HistoryIcon className="w-5 h-5"/></button>
                    <button onClick={onResetChat} className="p-2.5 rounded-xl text-text-secondary hover:bg-surface hover:text-white transition-all shadow-sm"><RefreshIcon className="w-5 h-5"/></button>
                    <div className="w-px h-6 bg-border/50 mx-1"></div>
                    <button onClick={onOpenVoiceModal} className="p-2.5 rounded-xl text-text-secondary hover:bg-surface hover:text-white transition-all shadow-sm"><SettingsIcon className="w-5 h-5"/></button>
                    <button onClick={onToggleTts} className={`p-2.5 rounded-xl transition-all shadow-sm ${isTtsEnabled ? 'bg-primary/20 text-primary' : 'text-text-secondary hover:bg-surface hover:text-white'}`}>
                        {isTtsEnabled ? <SpeakerOnIcon className="w-5 h-5"/> : <SpeakerOffIcon className="w-5 h-5"/>}
                    </button>
                </div>
            </div>

            <div className="flex-grow p-4 overflow-y-auto space-y-4 scroll-smooth custom-scrollbar">
                {chatHistory.map((msg, index) => {
                    const currentDate = msg.timestamp ? new Date(msg.timestamp) : null;
                    const prevDate = index > 0 && chatHistory[index-1].timestamp ? new Date(chatHistory[index-1].timestamp!) : null;
                    const showDate = currentDate && (!prevDate || currentDate.toDateString() !== prevDate.toDateString());
                    return (
                        <React.Fragment key={msg.id}>
                            {showDate && <TimeSeparator date={currentDate!} />}
                            <ChatMessageBubble msg={msg} onSpeak={onSpeak} cancelSpeaking={cancelSpeaking} speakingText={speakingText} onSendMessage={onSendMessage} setMessageFeedback={setMessageFeedback} />
                        </React.Fragment>
                    );
                })}
                {isLoading && chatHistory.length > 0 && chatHistory[chatHistory.length - 1]?.sender === 'user' && (
                     <div className="flex items-start gap-4 my-6 animate-fade-in">
                        <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-primary to-accent flex-shrink-0 flex items-center justify-center font-bold text-white shadow-glow-primary">AI</div>
                        <div className="px-5 py-4 rounded-2xl bg-surface/60 backdrop-blur-sm border border-white/5">
                            <div className="flex gap-1.5">
                                <div className="w-2 h-2 bg-accent rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                                <div className="w-2 h-2 bg-accent rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                                <div className="w-2 h-2 bg-accent rounded-full animate-bounce"></div>
                            </div>
                        </div>
                    </div>
                )}
                <div ref={messagesEndRef} />
            </div>

            {followUpSuggestions.length > 0 && !isLoading && (
                <div className="px-6 pb-2 flex-shrink-0 flex flex-wrap gap-2 justify-center animate-slide-up">
                    {followUpSuggestions.map((s, i) => (
                        <button key={i} onClick={() => onSendMessage(s)} className="px-4 py-2 text-xs font-semibold bg-surface/60 border border-border/50 rounded-full hover:bg-primary/20 hover:border-primary/50 text-text-secondary hover:text-primary transition-all shadow-sm">
                            {s}
                        </button>
                    ))}
                </div>
            )}

            <form onSubmit={handleFormSubmit} className="p-4 sm:p-6 flex-shrink-0 bg-gradient-to-t from-background via-background to-transparent">
                {attachedFiles.length > 0 && <AttachmentPreview files={attachedFiles} onRemove={onRemoveFile} />}

                {isProjectLoaded && (
                    <div className="flex justify-center mb-3">
                         <button type="button" onClick={onToggleProjectContext} className={`flex items-center gap-2 px-4 py-1.5 text-[10px] font-black uppercase tracking-widest rounded-full border transition-all ${isProjectContextEnabled ? 'bg-primary/20 border-primary text-primary shadow-glow-primary' : 'bg-surface/50 border-border/50 text-text-tertiary opacity-70'}`}>
                            <CodeIcon className="w-3.5 h-3.5" />
                            <span>Contexto Proyecto: {isProjectContextEnabled ? 'Activado' : 'Desactivado'}</span>
                        </button>
                    </div>
                )}

                <div className="relative group max-w-4xl mx-auto">
                    <div className="absolute -inset-1 bg-gradient-to-r from-primary/20 to-accent/20 rounded-2xl blur opacity-0 group-focus-within:opacity-100 transition duration-500"></div>
                    <div className="relative flex items-end gap-2 p-2 bg-surface/90 backdrop-blur-xl border border-border/50 rounded-2xl shadow-2xl focus-within:border-primary/50 transition-all">
                        <input type="file" ref={fileInputRef} onChange={e => e.target.files && onAddFiles(e.target.files)} multiple className="hidden"/>
                        <button type="button" onClick={() => fileInputRef.current?.click()} className="p-3 rounded-xl text-text-tertiary hover:text-white hover:bg-white/5 transition-all"><PaperclipIcon className="w-5 h-5"/></button>
                        <textarea
                            value={inputValue}
                            onChange={e => onInputChange(e.target.value)}
                            onKeyDown={e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); if (inputValue.trim() || attachedFiles.length > 0) handleFormSubmit(e as any); } }}
                            placeholder="Describe tu requerimiento o adjunta archivos..."
                            className="w-full p-3 bg-transparent text-text-primary placeholder-text-tertiary outline-none resize-none max-h-48 min-h-[50px] font-sans text-sm sm:text-base leading-relaxed"
                            rows={1}
                        />
                        <div className="flex items-center gap-1.5 pb-1 pr-1">
                            <button type="button" onClick={isListening ? stopListening : startListening} className={`p-3 rounded-xl transition-all ${isListening ? 'bg-error/20 text-error animate-pulse' : 'text-text-tertiary hover:text-white hover:bg-white/5'}`} title="Dictado por voz">
                                <MicrophoneIcon className="w-5 h-5"/>
                            </button>
                            <button type="submit" disabled={isLoading || (!inputValue.trim() && attachedFiles.length === 0)} className="p-3 rounded-xl bg-primary text-white hover:bg-primary-focus transition-all transform active:scale-90 disabled:opacity-30 disabled:grayscale shadow-lg shadow-primary/20 flex-shrink-0">
                                <SendIcon className="w-5 h-5" />
                            </button>
                        </div>
                    </div>
                </div>
            </form>
        </div>
    );
};

import React, { Component, ErrorInfo, ReactNode } from 'react';
import { AlertTriangleIcon, RefreshIcon } from './ui/icons';
import { I18nContext } from '../contexts/I18nContext';
import { TranslationKey } from '../i18n/translations';

interface ErrorBoundaryProps {
  // FIX: Made children optional to ensure compatibility with standard JSX usage and React typing.
  children?: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
}

// FIX: Extend Component directly from 'react' to resolve TypeScript recognition issues with the props and state properties.
export class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  // FIX: Explicitly initialize state and declare its type on the class for improved TypeScript property recognition.
  public state: ErrorBoundaryState = {
    hasError: false,
    error: null
  };

  constructor(props: ErrorBoundaryProps) {
    super(props);
  }

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("ErrorBoundary caught an error:", error, errorInfo);
  }

  handleReset = () => {
    window.location.reload();
  };

  render(): ReactNode {
    // FIX: Destructure state and props to ensure local variables have correct type inference and avoid repeated 'this' access.
    const { hasError, error } = this.state;
    const { children } = this.props;

    if (hasError) {
      return (
        <I18nContext.Consumer>
          {(i18n) => {
            const t = i18n?.t || ((key: string) => key);
            return (
              <div className="min-h-screen w-full flex items-center justify-center bg-background p-6 font-sans">
                {/* Background Decorations */}
                <div className="fixed inset-0 overflow-hidden pointer-events-none">
                  <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-error/10 rounded-full blur-[120px] animate-pulse"></div>
                  <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-primary/10 rounded-full blur-[120px] animate-pulse" style={{ animationDelay: '1s' }}></div>
                </div>

                <div className="relative z-10 w-full max-w-2xl bg-surface/40 backdrop-blur-xl border border-error/30 rounded-2xl p-8 md:p-12 shadow-2xl shadow-error/10 animate-fade-in text-center">
                  <div className="inline-flex items-center justify-center w-20 h-20 rounded-full bg-error/20 border-2 border-error/40 mb-8 shadow-glow-primary">
                    <AlertTriangleIcon className="w-10 h-10 text-error" />
                  </div>

                  <h1 className="text-3xl md:text-4xl font-bold text-text-primary mb-4 drop-shadow-text-glow-primary">
                    {t('errorBoundary.title' as TranslationKey)}
                  </h1>

                  <p className="text-lg text-text-secondary mb-8 leading-relaxed">
                    {t('errorBoundary.description' as TranslationKey)}
                  </p>

                  <div className="bg-black/40 rounded-xl p-6 mb-8 border border-white/5 text-left overflow-hidden">
                    <p className="text-xs font-bold text-error/70 uppercase tracking-widest mb-3">
                      {t('errorBoundary.details' as TranslationKey)}
                    </p>
                    <div className="font-mono text-sm text-error/90 break-words max-h-40 overflow-y-auto custom-scrollbar">
                      {/* FIX: Use the destructured 'error' state variable for consistent access. */}
                      {error?.message || t('errorBoundary.unknown' as TranslationKey)}
                    </div>
                  </div>

                  <div className="flex flex-col sm:flex-row gap-4 justify-center">
                    <button
                      onClick={this.handleReset}
                      className="inline-flex items-center justify-center gap-2 px-8 py-3 bg-gradient-to-r from-error to-primary text-white font-bold rounded-lg hover:brightness-110 transition-all transform hover:scale-105 shadow-lg shadow-error/20"
                    >
                      <RefreshIcon className="w-5 h-5" />
                      {t('errorBoundary.reload' as TranslationKey)}
                    </button>
                    <a 
                      href="/"
                      className="inline-flex items-center justify-center px-8 py-3 bg-surface border border-border text-text-primary font-semibold rounded-lg hover:bg-border transition-all"
                    >
                      Ir al Inicio
                    </a>
                  </div>
                </div>
              </div>
            );
          }}
        </I18nContext.Consumer>
      );
    }

    // FIX: Return destructured children when no error is caught.
    return children;
  }
}

import { GoogleGenAI, Type, Schema, Chat, LiveServerMessage, Modality, Part, GenerateContentResponse } from "@google/genai";
import { TechStack, AnalysisIssue, LinkAnalysisResult, WireframeData, WireframeCodeResult, UIMagicianResult, ImageEditResult, CodeTranslatorResult, CodeCompletionSuggestion, CodeDiagnostic, DeploymentPlatform, DeploymentFile, TechValue, ProjectFile, AspectRatio } from '../types';

/**
 * Factory function to always get a fresh instance of the AI client.
 * Essential for ensuring the most up-to-date API key and session integrity.
 */
const getAI = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

// --- Helper Functions ---

async function safeGenerateContent(params: { model: string; contents: any; config?: any }): Promise<GenerateContentResponse> {
    const ai = getAI();
    try {
        const response = await ai.models.generateContent(params);
        return response;
    } catch (error) {
        console.error("Gemini API Error:", error);
        throw error;
    }
}

function formatTechStack(techStack: TechStack): string {
    return `Frontend: ${techStack.frontend}, Backend: ${techStack.backend}, Database: ${techStack.database}, Mobile: ${techStack.mobile}, DevOps: ${techStack.devops.join(', ')}`;
}

// --- Architect Service ---

export const generateClarificationQuestions = async (description: string, techStack: TechStack): Promise<string[]> => {
    const prompt = `Analiza la siguiente idea de proyecto y el stack tecnológico. Genera de 3 a 5 preguntas clave para aclarar los requisitos funcionales y técnicos antes de diseñar la arquitectura.

    Proyecto: "${description}"
    Stack: ${formatTechStack(techStack)}

    Responde estrictamente con un array JSON de strings.`;

    const response = await safeGenerateContent({
        model: 'gemini-3-flash-preview',
        contents: [{ parts: [{ text: prompt }] }],
        config: { 
            responseMimeType: 'application/json'
        }
    });
    return JSON.parse(response.text || '[]');
};

export const startClarificationChat = (initialDescription: string): Chat => {
    const ai = getAI();
    return ai.chats.create({
        model: 'gemini-3-flash-preview',
        config: {
            systemInstruction: `Eres un arquitecto de software experto. Tu objetivo es aclarar los requisitos del proyecto: "${initialDescription}". Haz preguntas concisas y útiles para definir la arquitectura final.`,
        }
    });
};

export const generateProjectArchitecture = async (description: string, techStack: TechStack, history: any[]): Promise<{path: string, content: string}[]> => {
    const prompt = `Genera la estructura completa de archivos y el código base inicial para este proyecto.
    Descripción: ${description}
    Stack: ${formatTechStack(techStack)}
    Contexto adicional (Chat): ${history.map(m => `${m.sender}: ${m.text}`).join('\n')}

    Asegúrate de que el código sea profesional, modular y siga las mejores prácticas del stack elegido.
    Devuelve un array JSON de objetos {path: string, content: string}.`;

    const response = await safeGenerateContent({
        model: 'gemini-3-pro-preview',
        contents: [{ parts: [{ text: prompt }] }],
        config: { 
            responseMimeType: 'application/json',
            thinkingConfig: { thinkingBudget: 16384 } // High budget for complex architectural design
        }
    });
    return JSON.parse(response.text || '[]');
};

export const modifyProjectArchitecture = async (currentFiles: {path: string, content: string}[], techStack: TechStack, request: string): Promise<{path: string, content: string}[]> => {
    const prompt = `Modifica la arquitectura del proyecto existente según la solicitud del usuario.
