    const [isHuboShellOpen, setIsHuboShellOpen] = useState(false);
    const chatHook = useChat();

    const konamiCallback = useCallback(() => {
        setIsHuboShellOpen(true);
        openModal('killcontra', {
            title: 'GOD MODE ACTIVATED',
            message: <div className="text-center font-mono"><p className="text-accent text-2xl animate-pulse">TERMINAL OVERRIDE ENABLED</p><p className="mt-2 text-xs opacity-60">You have accessed the core logic shell.</p></div>,
            confirmText: 'Enter Shell', onConfirm: () => {}
        });
    }, [openModal]);

    useKonamiCode(konamiCallback);

    const renderContent = () => {
        if (!activeMode) return <WelcomeScreen onSelectMode={setActiveMode} currentUser={currentUser} onOpenAuthModal={() => openModal('auth', {})} onLogout={logout} onReset={() => setActiveMode(null)} />;
        return (
            <Suspense fallback={<Loader text="Restaurando Módulo..." />}>
                {(() => {
                    switch (activeMode) {
                        case 'chat': return <div className="flex flex-col h-full items-center px-4 max-w-4xl mx-auto"><ChatInterface {...chatHook} onSpeak={speechHook.speak} cancelSpeaking={speechHook.cancelSpeaking} speakingText={speechHook.speakingText} isListening={speechHook.isListening} startListening={speechHook.startListening} stopListening={speechHook.stopListening} isTtsEnabled={speechHook.isTtsEnabled} onToggleTts={speechHook.toggleTts} onOpenVoiceModal={() => openModal('settings', { speechHook })} onOpenHistory={() => openModal('chatHistory', { conversations: chatHook.conversationLog, onLoadConversation: chatHook.loadConversation, onDeleteConversation: chatHook.deleteConversation, onNewChat: chatHook.resetChat })} /></div>;
                        case 'architect': return <ArchitectFlow onSendToDoctor={() => setActiveMode('doctor')} onSendToDeployer={() => setActiveMode('deployer')} />;
                        case 'doctor': return <CodeDoctorFlow />;
                        case 'tutor': return <TestTutorFlow />;
                        case 'magician': return <UIMagicianFlow onSendToDoctor={(res) => setActiveMode('doctor')} />;
                        case 'deployer': return <DeployerFlow />;
                        case 'community': return <CommunityHubFlow />;
                        case 'wireframe': return <WireframeFlow onSendToDoctor={(res) => setActiveMode('doctor')} />;
                        case 'translator': return <CodeTranslatorFlow />;
                        case 'donation': return <DonationFlow />;
                        case 'videoAnalyst': return <VideoAnalystFlow />;
                        case 'codeCopilot': return <CodeCopilotFlow />;
                        case 'navigator': return <WebNavigatorFlow onSendToDoctor={(res) => setActiveMode('doctor')} onAnalyzeFilesInDoctor={(files, tech, name) => setActiveMode('doctor')} />;
                        case 'liveChat': return <LiveChatFlow />;
                        case 'guardian': return <GuardianFlow />;
                        default: return <div>Módulo no encontrado.</div>;
                    }
                })()}
            </Suspense>
        );
    };

    return (
        <div className="flex h-screen bg-background relative overflow-hidden">
            <HuboShell isOpen={isHuboShellOpen} onClose={() => setIsHuboShellOpen(false)} />
            {activeMode && <SidebarNav activeMode={activeMode} isSidebarVisible={isSidebarVisible} onSelectMode={setActiveMode} onReset={() => setActiveMode(null)} onOpenSettings={() => openModal('settings', { speechHook })} onOpenSupport={() => openModal('support', {})} currentUser={currentUser} onOpenAuth={() => openAuth()} onLogout={logout} onToggleSidebar={() => setIsSidebarVisible(!isSidebarVisible)} />}
