import React, { Component, ErrorInfo, ReactNode } from 'react';
import { AlertTriangleIcon, RefreshIcon } from './ui/icons';
import { I18nContext } from '../contexts/I18nContext';
import { TranslationKey } from '../i18n/translations';

interface ErrorBoundaryProps {
  children?: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
}

// FIX: Explicitly extending Component and using specific imports from 'react' to ensure inherited 'props' and 'state' are correctly recognized by the TypeScript compiler.
export class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  public state: ErrorBoundaryState = {
    hasError: false,
    error: null
  };

  constructor(props: ErrorBoundaryProps) {
    super(props);
  }

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { hasError: true, error };
  }

  // FIX: Using ErrorInfo type from the specific import instead of React namespace.
  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("ErrorBoundary caught an error:", error, errorInfo);
  }

  handleReset = () => {
    window.location.reload();
  };

  // FIX: Using ReactNode return type from the specific import.
  render(): ReactNode {
    // FIX: Accessing inherited this.state and this.props from the Component class instance.
    const { hasError, error } = this.state;
    const { children } = this.props;

    if (hasError) {
      return (
        <I18nContext.Consumer>
          {(i18n) => {
            const t = i18n?.t || ((key: string) => key);
            return (
              <div className="min-h-screen w-full flex items-center justify-center bg-background p-6 font-sans">
                {/* Background Decorations */}
                <div className="fixed inset-0 overflow-hidden pointer-events-none">
                  <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-error/10 rounded-full blur-[120px] animate-pulse"></div>
                  <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-primary/10 rounded-full blur-[120px] animate-pulse" style={{ animationDelay: '1s' }}></div>
                </div>

                <div className="relative z-10 w-full max-w-2xl bg-surface/40 backdrop-blur-xl border border-error/30 rounded-2xl p-8 md:p-12 shadow-2xl shadow-error/10 animate-fade-in text-center">
                  <div className="inline-flex items-center justify-center w-20 h-20 rounded-full bg-error/20 border-2 border-error/40 mb-8 shadow-glow-primary">
                    <AlertTriangleIcon className="w-10 h-10 text-error" />
                  </div>

                  <h1 className="text-3xl md:text-4xl font-bold text-text-primary mb-4 drop-shadow-text-glow-primary">
                    {t('errorBoundary.title' as TranslationKey)}
                  </h1>

                  <p className="text-lg text-text-secondary mb-8 leading-relaxed">
                    {t('errorBoundary.description' as TranslationKey)}
                  </p>

                  <div className="bg-black/40 rounded-xl p-6 mb-8 border border-white/5 text-left overflow-hidden">
                    <p className="text-xs font-bold text-error/70 uppercase tracking-widest mb-3">
                      {t('errorBoundary.details' as TranslationKey)}
                    </p>
                    <div className="font-mono text-sm text-error/90 break-words max-h-40 overflow-y-auto custom-scrollbar">
                      {error?.message || t('errorBoundary.unknown' as TranslationKey)}
                    </div>
                  </div>

                  <div className="flex flex-col sm:flex-row gap-4 justify-center">
                    <button
                      onClick={this.handleReset}
                      className="inline-flex items-center justify-center gap-2 px-8 py-3 bg-gradient-to-r from-error to-primary text-white font-bold rounded-lg hover:brightness-110 transition-all transform hover:scale-105 shadow-lg shadow-error/20"
                    >
                      <RefreshIcon className="w-5 h-5" />
                      {t('errorBoundary.reload' as TranslationKey)}
                    </button>
                    <a 
                      href="/"
                      className="inline-flex items-center justify-center px-8 py-3 bg-surface border border-border text-text-primary font-semibold rounded-lg hover:bg-border transition-all"
                    >
                      Ir al Inicio
                    </a>
                  </div>
                </div>
              </div>
            );
          }}
        </I18nContext.Consumer>
      );
    }

    return children;
  }
}

import { useState, useEffect, useCallback } from 'react';
import { ChatMessage, CodeDiagnostic, Conversation } from '../types';
import * as geminiService from '../services/geminiService';
import { Chat, Part } from '@google/genai';
import { useToastContext } from '../contexts/ToastContext';
import { useProjectContext } from '../contexts/ProjectContext';
import { useI18n } from '../contexts/I18nContext';

type AttachedFile = {
    name: string;
    mimeType: string;
    content: string; 
    isImage: boolean;
    isVideo: boolean;
    previewUrl?: string; 
    contentSnippet?: string; 
    isLoading: boolean;
};

const generateId = () => Date.now().toString(36) + Math.random().toString(36).substring(2);
const ACTIVE_CHAT_STORAGE_KEY = 'alphapp-ai-chat-history';
const CHAT_LOG_STORAGE_KEY = 'alphapp-ai-chat-log';

export const useChat = () => {
    const { t } = useI18n();
    const { addToast } = useToastContext();
    const { projectFiles, isProjectLoaded } = useProjectContext();
    const [isProjectContextEnabled, setIsProjectContextEnabled] = useState(false);

    const [chatSession, setChatSession] = useState<Chat | null>(null);
    const [conversationLog, setConversationLog] = useState<Conversation[]>(() => {
        try {
            const savedLog = window.localStorage.getItem(CHAT_LOG_STORAGE_KEY);
            return savedLog ? JSON.parse(savedLog) : [];
        } catch (error) {
            return [];
        }
    });

    const [currentConversationId, setCurrentConversationId] = useState<string | null>(null);
    const [chatHistory, setChatHistory] = useState<ChatMessage[]>(() => {
        try {
            const savedHistory = window.localStorage.getItem(ACTIVE_CHAT_STORAGE_KEY);
            if (savedHistory) {
                const parsedHistory = JSON.parse(savedHistory);
                if (Array.isArray(parsedHistory) && parsedHistory.length > 0) return parsedHistory;
            }
        } catch (error) {}
        return [{ id: generateId(), sender: 'ai', text: t('chat.initialMessage' as any), timestamp: Date.now() }];
    });

    const [inputValue, setInputValue] = useState(''); // REFIJO: Nombre alineado con ChatInterface
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [attachedFiles, setAttachedFiles] = useState<AttachedFile[]>([]);
    const [followUpSuggestions, setFollowUpSuggestions] = useState<string[]>([]);

    const saveCurrentConversation = useCallback(async () => {
        if (chatHistory.length <= 1 && attachedFiles.length === 0) return;
        let title = "Nueva Conversación";
        let updatedLog = [...conversationLog];

        if (currentConversationId) {
            const index = updatedLog.findIndex(c => c.id === currentConversationId);
            if (index !== -1) {
                updatedLog[index] = { ...updatedLog[index], messages: chatHistory, timestamp: Date.now() };
            }
        } else {
            const firstUserMessage = chatHistory.find(m => m.sender === 'user')?.text;
            if (firstUserMessage) {
                try {
                    title = await geminiService.getQuickAnswer(`Genera un título muy corto (máximo 5 palabras) para: "${firstUserMessage}"`);
                } catch (e) {
                    title = firstUserMessage.substring(0, 30) + '...';
                }
            }
            const newId = generateId();
            updatedLog.unshift({ id: newId, title, timestamp: Date.now(), messages: chatHistory });
            setCurrentConversationId(newId);
        }
        setConversationLog(updatedLog);
        window.localStorage.setItem(CHAT_LOG_STORAGE_KEY, JSON.stringify(updatedLog));
    }, [chatHistory, conversationLog, currentConversationId, attachedFiles.length]);

    useEffect(() => {
        window.localStorage.setItem(ACTIVE_CHAT_STORAGE_KEY, JSON.stringify(chatHistory));
    }, [chatHistory]);

    useEffect(() => {
        setChatSession(geminiService.startChat(chatHistory));
    }, []);

    const addFiles = useCallback((files: FileList) => {
        if (!files) return;
        for (const file of Array.from(files)) {
            const reader = new FileReader();
            const isImage = file.type.startsWith('image/');
            const isVideo = file.type.startsWith('video/');
            setAttachedFiles(prev => [...prev, { name: file.name, mimeType: file.type, content: '', isImage, isVideo, isLoading: true }]);
            reader.onload = (e) => {
                const result = e.target?.result as string;
                setAttachedFiles(prev => prev.map(f => f.name === file.name ? {
                    ...f, content: result.includes(',') ? result.split(',')[1] : result,
                    previewUrl: (isImage || isVideo) ? result : undefined,
                    contentSnippet: (!isImage && !isVideo) ? result.substring(0, 100) : undefined,
                    isLoading: false
                } : f));
            };
            if (isImage || isVideo) reader.readAsDataURL(file);
            else reader.readAsText(file);
        }
    }, []);

    const removeFile = useCallback((name: string) => setAttachedFiles(prev => prev.filter(f => f.name !== name)), []);

    const sendMessage = useCallback(async (message: string) => {
        if (isLoading || !chatSession) return;
        setIsLoading(true);
        setError(null);
        setFollowUpSuggestions([]);

        const userMessage: ChatMessage = { id: generateId(), sender: 'user', text: message, timestamp: Date.now(), files: attachedFiles.map(f => ({ name: f.name, isImage: f.isImage, isVideo: f.isVideo })) };
        const currentHistoryWithUserMessage = [...chatHistory, userMessage];
        setChatHistory(currentHistoryWithUserMessage);

        const parts: (string | Part)[] = [{ text: message }];
        attachedFiles.forEach(file => parts.push({ inlineData: { mimeType: file.mimeType, data: file.content } }));

        if (isProjectContextEnabled && projectFiles?.length) {
            const projectContext = projectFiles.map(f => `--- ${f.path} ---\n${f.content}`).join('\n\n');
            parts.unshift({ text: `Contexto del proyecto:\n\`\`\`\n${projectContext}\n\`\`\`\n\nPregunta del usuario:` });
        }
        setAttachedFiles([]);
        const aiMessageId = generateId();
        setChatHistory(prev => [...prev, { id: aiMessageId, sender: 'ai', text: '', sources: [], timestamp: Date.now() }]);

        try {
            const stream = await geminiService.sendMessageToAI(chatSession, parts);
            let fullResponse = '';
            for await (const chunk of stream) {
                const groundingMetadata = chunk.candidates?.[0]?.groundingMetadata;
                if (groundingMetadata?.groundingChunks) {
                    const sources = groundingMetadata.groundingChunks.map(c => c.web).filter(web => web?.uri) as { uri: string; title: string }[];
                    if (sources.length > 0) {
                        setChatHistory(prev => {
                            const newHistory = [...prev];
                            const lastMessage = newHistory[newHistory.length - 1];
                            if (lastMessage?.sender === 'ai') {
                                const existingUris = new Set((lastMessage.sources || []).map(s => s.uri));
                                const newSources = sources.filter(s => !existingUris.has(s.uri));
                                if (newSources.length > 0) lastMessage.sources = [...(lastMessage.sources || []), ...newSources];
                            }
                            return newHistory;
                        });
                    }
                }
                if (chunk.text) {
                    fullResponse += chunk.text;
                    setChatHistory(prev => {
                        const newHistory = [...prev];
                        newHistory[newHistory.length - 1] = { ...newHistory[newHistory.length - 1], text: fullResponse };
                        return newHistory;
                    });
                }
            }
            const suggestions = await geminiService.generateFollowUpSuggestions([...currentHistoryWithUserMessage, { id: aiMessageId, sender: 'ai', text: fullResponse }]);
            setFollowUpSuggestions(suggestions);
        } catch (e) {
            const errorMessage = e instanceof Error ? e.message : 'Error desconocido.';
            setChatHistory(prev => prev.map(m => m.id === aiMessageId ? { ...m, text: `Error: ${errorMessage}` } : m));
        } finally {
            setIsLoading(false);
            saveCurrentConversation();
        }
    }, [isLoading, chatSession, attachedFiles, isProjectContextEnabled, projectFiles, chatHistory, saveCurrentConversation]);

    const resetChat = useCallback(async () => {
        await saveCurrentConversation();
        setCurrentConversationId(null);
        setChatHistory([{ id: generateId(), sender: 'ai', text: t('chat.initialMessage' as any), timestamp: Date.now() }]);
        setInputValue('');
        setAttachedFiles([]);
        setFollowUpSuggestions([]);
        setChatSession(geminiService.startChat());
    }, [saveCurrentConversation, t]);

    return {
        chatHistory, sendMessage, isLoading, error, inputValue, onInputChange: setInputValue, // REFIJO: Mapeo correcto para spread
        attachedFiles, addFiles, removeFile, resetChat, conversationLog, loadConversation: (id: string) => {
            const conv = conversationLog.find(c => c.id === id);
            if (conv) { setChatHistory(conv.messages); setCurrentConversationId(id); setChatSession(geminiService.startChat(conv.messages)); }
        }, 
        deleteConversation: (id: string) => {
            const updated = conversationLog.filter(c => c.id !== id);
            setConversationLog(updated); window.localStorage.setItem(CHAT_LOG_STORAGE_KEY, JSON.stringify(updated));
            if (currentConversationId === id) resetChat();
        },
        followUpSuggestions, setMessageFeedback: (mid: string, f: 'good' | 'bad') => setChatHistory(prev => prev.map(m => m.id === mid ? { ...m, feedback: f } : m)),
        isProjectLoaded, isProjectContextEnabled, toggleProjectContext: () => setIsProjectContextEnabled(!isProjectContextEnabled)
    };
};

