                            <div className="w-1.5 h-1.5 rounded-full bg-current animate-pulse" />
                            <span>Red Segura</span>
                        </div>
                    </div>
                    <span className="flex items-center gap-1"><SpinnerIcon className="w-3 h-3"/> Procesamiento Distribuido Activo</span>
                </div>
            </div>
        </div>
    );
};

